import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Alert,
  Divider,
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import DownloadIcon from '@mui/icons-material/Download';

interface FailureAnalysisData {
  analyzed_at: string;
  database: {
    total_failed_runs: number;
    with_results_json: number;
    without_results_json: number;
    error_categories: Record<string, number>;
    recent_failures: Array<{
      run_id: string;
      entry_id: number;
      error_message: string;
      failed_at: string;
    }>;
  };
  results_files: {
    runs_analyzed: number;
    task_failures: Record<string, number>;
    failure_points: Record<string, number>;
  };
  summary: {
    total_db_failures: number;
    hung_before_completion: number;
    most_common_error_category: [string, number] | null;
  };
  recommendations: string[];
}

export default function ValidationFailureAnalysis() {
  const [data, setData] = useState<FailureAnalysisData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const runAnalysis = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch('/validation/stats/failure-analysis');
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const result = await response.json();
      setData(result);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    runAnalysis();
  }, []);

  const handleExport = () => {
    if (!data) return;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `failure-analysis-${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  if (loading && !data) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 3 }}>
        {error}
      </Alert>
    );
  }

  if (!data) return null;

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Typography variant="h5" fontWeight="600" gutterBottom>
            Failure Analysis
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Detailed analysis of validation failures
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            variant="outlined"
            startIcon={<RefreshIcon />}
            onClick={runAnalysis}
            disabled={loading}
          >
            Refresh
          </Button>
          <Button
            variant="outlined"
            startIcon={<DownloadIcon />}
            onClick={handleExport}
          >
            Export JSON
          </Button>
        </Box>
      </Box>

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Total Failed Runs
              </Typography>
              <Typography variant="h4" fontWeight="bold" color="error.main">
                {data.database.total_failed_runs.toLocaleString()}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                With Results JSON
              </Typography>
              <Typography variant="h4" fontWeight="bold">
                {data.database.with_results_json.toLocaleString()}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Without Results
              </Typography>
              <Typography variant="h4" fontWeight="bold" color="warning.main">
                {data.database.without_results_json.toLocaleString()}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card>
            <CardContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Runs Analyzed
              </Typography>
              <Typography variant="h4" fontWeight="bold">
                {data.results_files.runs_analyzed.toLocaleString()}
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" fontWeight="600" gutterBottom>
              Error Categories
            </Typography>
            <Divider sx={{ mb: 2 }} />
            {Object.entries(data.database.error_categories)
              .sort((a, b) => b[1] - a[1])
              .slice(0, 10)
              .map(([category, count]) => (
                <Box key={category} sx={{ display: 'flex', justifyContent: 'space-between', py: 1 }}>
                  <Typography variant="body2">{category}</Typography>
                  <Typography variant="body2" fontWeight="600">{count.toLocaleString()}</Typography>
                </Box>
              ))}
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" fontWeight="600" gutterBottom>
              Task Failures
            </Typography>
            <Divider sx={{ mb: 2 }} />
            {Object.entries(data.results_files.task_failures)
              .sort((a, b) => b[1] - a[1])
              .slice(0, 10)
              .map(([task, count]) => (
                <Box key={task} sx={{ display: 'flex', justifyContent: 'space-between', py: 1 }}>
                  <Typography variant="body2">{task}</Typography>
                  <Typography variant="body2" fontWeight="600">{count.toLocaleString()}</Typography>
                </Box>
              ))}
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" fontWeight="600" gutterBottom>
              Recent Failures
            </Typography>
            <Divider sx={{ mb: 2 }} />
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell><strong>Run ID</strong></TableCell>
                    <TableCell><strong>Entry ID</strong></TableCell>
                    <TableCell><strong>Error</strong></TableCell>
                    <TableCell><strong>Failed At</strong></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {data.database.recent_failures.slice(0, 10).map((failure) => (
                    <TableRow key={failure.run_id} hover>
                      <TableCell>
                        <Typography variant="body2" fontWeight="500">
                          {failure.run_id}
                        </Typography>
                      </TableCell>
                      <TableCell>{failure.entry_id}</TableCell>
                      <TableCell>
                        <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 400, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          {failure.error_message || 'N/A'}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" color="text.secondary">
                          {new Date(failure.failed_at).toLocaleString('cs-CZ')}
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>

        {data.recommendations.length > 0 && (
          <Grid item xs={12}>
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" fontWeight="600" gutterBottom>
                Recommendations
              </Typography>
              <Divider sx={{ mb: 2 }} />
              {data.recommendations.map((rec, i) => (
                <Box key={i} sx={{ display: 'flex', gap: 2, mb: 1 }}>
                  <Typography variant="body2" color="primary.main" fontWeight="600">
                    {i + 1}.
                  </Typography>
                  <Typography variant="body2">{rec}</Typography>
                </Box>
              ))}
            </Paper>
          </Grid>
        )}
      </Grid>
    </Box>
  );
}
